"use client"

import * as React from "react"

/*
 * Keystone Crossing — a one-page portfolio for Kedhareswer, told as a camera move through a stone-bridge town.
 * One pinned stage: the hero bridge zooms until its arch frames the screen, the camera passes through it into the
 * riverside town, and a row of frosted project cards slides in over the rooftops. A contact band closes the page.
 * Every picture is an original ChatGPT image served from the component site; the bridge layer is cut from the hero
 * photo itself, so the two always line up.
 */

const ASSETS = "https://kedhar-components.pages.dev/keystone-crossing-template/"

// #region motion
export const clamp = (v: number, a = 0, b = 1) => (v < a ? a : v > b ? b : v)
/** 0 → 1 as p moves from a to b */
export const seg = (p: number, a: number, b: number) => clamp((p - a) / (b - a))
export const smooth = (t: number) => t * t * (3 - 2 * t)
export const easeOut = (t: number) => 1 - Math.pow(1 - t, 3)
export const easeInOut = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2)
const mix = (a: number, b: number, t: number) => a + (b - a) * t

/** scroll progress (0..1 of the pinned stage) for each nav stop */
export const STOPS = { intro: 0, bridge: 0.27, town: 0.55, work: 0.84 }

/**
 * The whole choreography as numbers, measured from the reference recording (forward scroll, 0 – 9.2 s, mapped
 * linearly onto the stage). `archScale` is how far the hero must zoom for the arch to span the screen, which
 * depends on the viewport's shape; `reduced` swaps every zoom, drift and blur for plain crossfades.
 */
export function frame(p: number, archScale = 2.2, reduced = false) {
  const out1 = smooth(seg(p, 0.075, 0.135)) // title leaves (0.7 – 1.25 s)
  const creep = smooth(seg(p, 0.03, 0.145)) // slow dolly while the title goes (0.3 – 1.33 s)
  const push = easeInOut(seg(p, 0.14, 0.2)) // then rush up to the arch (1.3 – 1.85 s)
  const drift = smooth(seg(p, 0.21, 0.36)) // keep gliding through it (1.9 – 3.3 s)
  const through = easeOut(seg(p, 0.352, 0.392)) // pass the arch (3.24 – 3.6 s)
  const archIn = easeOut(seg(p, 0.15, 0.205))
  const archOut = seg(p, 0.344, 0.36)
  const townIn = easeOut(seg(p, 0.352, 0.392))
  const copyIn = easeOut(seg(p, 0.435, 0.49))
  const copyOut = seg(p, 0.61, 0.665)
  const cardsIn = easeOut(seg(p, 0.745, 0.805))
  const cardsOut = seg(p, 0.935, 0.975)
  const z = reduced ? 0 : 1
  const s1 = 1.05 + z * (0.05 * creep + (archScale - 1.1) * push + archScale * 0.22 * drift + archScale * 1.4 * through)
  return {
    titleO: 1 - out1,
    titleB: z * 14 * out1,
    titleY: z * -60 * out1,
    heroO: 1 - smooth(seg(p, 0.07, 0.125)),
    heroB: z * 10 * seg(p, 0.07, 0.125),
    heroY: z * 26 * seg(p, 0.07, 0.125),
    s1Scale: s1,
    s1Y: 3.6 * (1 - push) + z * (-7 * drift - 4 * through), // vh: the arch rises as the camera climbs
    bgBlur: z * mix(0, 13, smooth(seg(p, 0.14, 0.2))),
    wash: 0.7 * smooth(seg(p, 0.15, 0.2)),
    s1O: 1 - smooth(seg(p, 0.354, 0.378)),
    archO: archIn * (1 - archOut),
    archB: z * (12 * (1 - archIn) + 10 * archOut),
    archY: z * (24 * (1 - archIn) - 30 * archOut),
    s2O: townIn,
    s2B: z * 16 * (1 - townIn),
    s2Scale: 1 + z * (0.12 * (1 - townIn) + 0.03 * (1 - smooth(seg(p, 0.4, 1)))),
    scrim: copyIn * (1 - copyOut),
    townO: copyIn * (1 - copyOut),
    townB: z * (10 * (1 - copyIn) + 10 * copyOut),
    townY: z * (18 * (1 - copyIn) - 16 * copyOut),
    cardsO: cardsIn * (1 - cardsOut),
    cardsB: z * (16 * (1 - cardsIn) + 16 * cardsOut),
    // vw: the row arrives from the right and keeps travelling left with the scroll
    cardsX: z * (26 * (1 - cardsIn) - 30 * smooth(seg(p, 0.77, 0.95))),
    section: p < 0.17 ? 0 : p < 0.39 ? 1 : p < 0.7 ? 2 : 3,
  }
}

/** how much the hero must zoom for the arch (745 of 1536 source px wide at the water) to run off both edges, as in the reference */
export function archScaleFor(w: number, h: number) {
  const k = Math.max(w / 1536, h / 1024)
  return Math.max(1.85, (1.31 * w) / (745 * k))
}
// #endregion

