export interface KeystoneCrossingTemplateProps {
  /** height of the pinned stage's viewport; a definite length (never a percentage) */
  height?: string
  /** how many stage-heights of scrolling the camera move takes */
  length?: number
  /** every call to action is a mailto: to this address */
  email?: string
  /** where hero.webp, bridge.webp and town.webp live */
  assetBase?: string
  className?: string
  style?: React.CSSProperties
}

export default function KeystoneCrossingTemplate({
  height = "100svh",
  length = 7,
  email = "kedhareswer.12110626@gmail.com",
  assetBase = ASSETS,
  className,
  style,
}: KeystoneCrossingTemplateProps) {
  const track = React.useRef(null as HTMLDivElement | null)
  const pin = React.useRef(null as HTMLDivElement | null)
  const [section, setSection] = React.useState(0)
  const [slide, setSlide] = React.useState(0)
  const pic = (k: string) => assetBase + k + ".webp"

  React.useEffect(() => {
    const t = track.current
    const root = pin.current
    if (!t || !root) return
    const q = (s: string) => root.querySelector(s) as HTMLElement
    const el = {
      s1: q(".kx-s1"), bg: q(".kx-bg"), wash: q(".kx-wash"), title: q(".kx-title"), hero: q(".kx-hero"),
      arch: q(".kx-arch"), s2: q(".kx-s2"), scrim: q(".kx-scrim"), town: q(".kx-town"), cards: q(".kx-cards"), hint: q(".kx-hint"),
    }
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
    let shown = -1
    let cur = -1
    let raf = 0
    const blur = (b: number) => (b > 0.05 ? "blur(" + b.toFixed(2) + "px)" : "none")
    const target = () => {
      const r = t.getBoundingClientRect()
      const run = r.height - root.clientHeight
      return run > 0 ? clamp(-r.top / run) : 0
    }
    const paint = (p: number) => {
      const f = frame(p, archScaleFor(root.clientWidth, root.clientHeight), mq.matches)
      el.s1.style.transform = "translate3d(0," + f.s1Y.toFixed(3) + "%,0) scale(" + f.s1Scale.toFixed(4) + ")"
      el.s1.style.opacity = f.s1O.toFixed(3)
      el.s1.style.visibility = f.s1O < 0.002 ? "hidden" : ""
      el.bg.style.filter = blur(f.bgBlur)
      el.wash.style.opacity = f.wash.toFixed(3)
      el.title.style.cssText = "opacity:" + f.titleO.toFixed(3) + ";filter:" + blur(f.titleB) + ";transform:translate3d(0," + f.titleY.toFixed(1) + "px,0)"
      el.hero.style.opacity = f.heroO.toFixed(3)
      el.hero.style.filter = blur(f.heroB)
      el.hero.style.transform = "translate3d(-50%," + f.heroY.toFixed(1) + "px,0)"
      el.hero.style.visibility = f.heroO < 0.01 ? "hidden" : ""
      el.hint.style.opacity = (1 - seg(p, 0, 0.04)).toFixed(3)
      el.arch.style.cssText = "opacity:" + f.archO.toFixed(3) + ";filter:" + blur(f.archB) + ";transform:translate3d(-50%," + f.archY.toFixed(1) + "px,0);visibility:" + (f.archO < 0.01 ? "hidden" : "visible")
      el.s2.style.opacity = f.s2O.toFixed(3)
      el.s2.style.filter = blur(f.s2B)
      el.s2.style.transform = "scale(" + f.s2Scale.toFixed(4) + ")"
      el.s2.style.visibility = f.s2O < 0.002 ? "hidden" : ""
      el.scrim.style.opacity = f.scrim.toFixed(3)
      el.town.style.cssText = "opacity:" + f.townO.toFixed(3) + ";filter:" + blur(f.townB) + ";transform:translate3d(-50%," + f.townY.toFixed(1) + "px,0);visibility:" + (f.townO < 0.01 ? "hidden" : "visible")
      el.cards.style.cssText = "opacity:" + f.cardsO.toFixed(3) + ";filter:" + blur(f.cardsB) + ";transform:translate3d(" + f.cardsX.toFixed(2) + "vw,0,0);visibility:" + (f.cardsO < 0.01 ? "hidden" : "visible")
      if (f.section !== shown) setSection((shown = f.section))
    }
    const tick = () => {
      raf = 0
      const goal = target()
      // a light trail behind the scrollbar, like the reference's smoothed wheel; none when motion is reduced
      cur = cur < 0 || mq.matches ? goal : cur + (goal - cur) * 0.14
      if (Math.abs(goal - cur) < 0.0004) cur = goal
      paint(cur)
      if (cur !== goal) raf = requestAnimationFrame(tick)
    }
    const kick = () => {
      if (!raf) raf = requestAnimationFrame(tick)
    }
    tick()
    window.addEventListener("scroll", kick, { passive: true })
    window.addEventListener("resize", kick)
    mq.addEventListener("change", kick)
    return () => {
      cancelAnimationFrame(raf)
      window.removeEventListener("scroll", kick)
      window.removeEventListener("resize", kick)
      mq.removeEventListener("change", kick)
    }
  }, [])

  const go = (stop: keyof typeof STOPS) => (e: React.MouseEvent) => {
    e.preventDefault()
    const t = track.current
    const root = pin.current
    if (!t || !root) return
    const r = t.getBoundingClientRect()
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    window.scrollTo({ top: window.scrollY + r.top + STOPS[stop] * (r.height - root.clientHeight) + 2, behavior: reduce ? "auto" : "smooth" })
  }

  const last = CARDS.length - 2
  return (
    <div className={"kx-root" + (className ? " " + className : "")} style={style}>
      <style>{CSS}</style>
      <div ref={track} className="kx-track" style={{ height: "calc(" + height + " * " + length + ")" }}>
        <div ref={pin} className="kx-pin" style={{ height }}>
          <div className="kx-scene kx-s1">
            <img className="kx-bg" src={pic("hero")} alt="A tall stone arch bridge between two towers over a turquoise river" width={1536} height={1024} draggable={false} />
            <div className="kx-wash" style={{ opacity: 0 }} />
            <img className="kx-br" src={pic("bridge")} alt="" width={1536} height={1024} draggable={false} />
          </div>
          <div className="kx-scene kx-s2" style={{ opacity: 0, visibility: "hidden" }}>
            <img src={pic("town")} alt="A riverside old town with a domed mosque, minarets and stone houses" width={1536} height={1024} draggable={false} loading="eager" />
            <div className="kx-scrim" style={{ opacity: 0 }} />
          </div>
          <div className="kx-shade" />

          <nav className="kx-nav" aria-label="Sections">
            <a className="kx-brand" href="#" onClick={go("intro")}>
              Kedhareswer
            </a>
            <div className="kx-links">
              {NAV.map(([label, stop], i) => (
                <a key={stop} href={"#" + stop} className={section === i ? "on" : ""} onClick={go(stop)}>
                  {label}
                </a>
              ))}
            </div>
            <span className="kx-lang">
              EN <Icon name="down" />
            </span>
          </nav>

          <h1 className="kx-title" aria-label="Kedhar">
            KEDHAR
          </h1>
          <div className="kx-hero">
            <p>A designer who builds for the web: calm interfaces, careful motion, and one unforgettable first impression.</p>
            <div className="kx-chips">
              <a className="kx-chip" href="#bridge" onClick={go("bridge")}>
                Interfaces
              </a>
              <a className="kx-chip" href="#town" onClick={go("town")}>
                Motion
              </a>
              <a className="kx-chip" href="#work" onClick={go("work")}>
                Selected work
              </a>
            </div>
          </div>
          <div className="kx-hint" aria-hidden="true">
            Scroll
          </div>

          <div className="kx-copy kx-arch" style={{ opacity: 0, visibility: "hidden" }}>
            <h2>
              The bridge is where
              <br />
              ideas cross.
            </h2>
            <p>Kedhareswer links product thinking with front-end craft, shipping interfaces shaped by research, motion and close attention to detail.</p>
            <div className="kx-stats">
              <div>
                <b>2019</b>
                <span>
                  First site
                  <br />
                  shipped
                </span>
              </div>
              <div>
                <b>40+</b>
                <span>
                  Projects built
                  <br />
                  with clients
                </span>
              </div>
            </div>
          </div>

          <div className="kx-copy kx-town" style={{ opacity: 0, visibility: "hidden" }}>
            <h2>
              The work keeps people
              <br />
              close.
            </h2>
            <p>Launch pages, dashboards and brand sites for Client 1, Client 2 and Client 3, each a short walk from first sketch to release.</p>
            <a className="kx-pill" href="#work" onClick={go("work")}>
              <Icon name="arrow" /> Open selected work
            </a>
          </div>

          <div className="kx-cards" style={{ opacity: 0, visibility: "hidden" }}>
            <div className="kx-row" style={{ transform: "translateX(calc((var(--cw) + var(--gap)) * " + -slide + "))" }}>
              {CARDS.map((c) => (
                <a key={c.title} className="kx-card" href={"mailto:" + email + "?subject=" + encodeURIComponent(c.title)}>
                  <small>{c.tag}</small>
                  <i>
                    <Icon name={c.icon} />
                  </i>
                  <h3>{c.title}</h3>
                  <p>{c.text}</p>
                </a>
              ))}
            </div>
            <div className="kx-arrows">
              <button type="button" aria-label="Previous project" disabled={slide === 0} onClick={() => setSlide((s) => Math.max(0, s - 1))}>
                <Icon name="left" />
              </button>
              <button type="button" aria-label="Next project" disabled={slide >= last} onClick={() => setSlide((s) => Math.min(last, s + 1))}>
                <Icon name="right" />
              </button>
            </div>
          </div>
        </div>
      </div>

      <section className="kx-end" aria-label="Contact">
        <div className="kx-end-grid">
          <div>
            <small>Routes · Contact</small>
            <h2>
              Let’s plan the
              <br />
              next crossing.
            </h2>
          </div>
          <div>
            <p>Kedhareswer takes on a few projects each season: product sites, dashboards, design systems and motion that earns its place.</p>
            <a className="kx-mail" href={"mailto:" + email}>
              {email} <Icon name="arrow" />
            </a>
            <div className="kx-clients" aria-label="Clients">
              <span>Client 1</span>
              <span>Client 2</span>
              <span>Client 3</span>
            </div>
          </div>
        </div>
        <div className="kx-photo">
          <img src={pic("town")} alt="" width={1536} height={1024} loading="lazy" draggable={false} />
          <span>From the first sketch to the far bank.</span>
        </div>
        <div className="kx-foot">
          <span>© 2026 Kedhareswer</span>
          <nav aria-label="Footer">
            <a href="#" onClick={go("intro")}>
              Back to the bridge
            </a>
            <a href={"mailto:" + email}>Email</a>
          </nav>
        </div>
      </section>
    </div>
  )
}
